	public function get_coin_statement($user_id, $start_date = null, $end_date = null)
	{
		// 1. Build custom datetime range
		if (!empty($start_date) && !empty($end_date)) {
			$start_datetime = date('Y-m-d H:i:s', strtotime($start_date . ' 12:00:00'));
			$end_datetime   = date('Y-m-d H:i:s', strtotime($end_date . ' +1 day 06:00:00'));
		}

		// 2. Fetch transactions
		$this->db->select("
        c.id, c.amount, c.created_at, c.status, c.type,
        l1.ledger_name AS sender_name,
        l2.ledger_name AS receiver_name,
        c.sender_id, c.receiver_id
    ");
		$this->db->from('coin_transactions c');
		$this->db->join('tbl_ledger l1', 'l1.id = c.sender_id', 'left');
		$this->db->join('tbl_ledger l2', 'l2.id = c.receiver_id', 'left');

		// Proper index-friendly condition
		$this->db->group_start()
			->where('c.receiver_id', $user_id)
			->or_group_start()
			->where('c.sender_id', $user_id)
			->where('c.type', 'spend')
			->group_end()
			->group_end();

		// Apply datetime range
		if (!empty($start_datetime) && !empty($end_datetime)) {
			$this->db->where('c.created_at >=', $start_datetime);
			$this->db->where('c.created_at <', $end_datetime);
		}

		$this->db->order_by('c.created_at', 'ASC');
		$transactions = $this->db->get()->result();

		// 3. Group transactions by date
		$tx_by_date = [];
		foreach ($transactions as $row) {
			$date = date('Y-m-d', strtotime($row->created_at));
			$tx_by_date[$date][] = $row;
		}

		// 4. Fetch P/L data for this user and range
		$this->db->select('date, today_hisab AS final_hisab');
		$this->db->from('tbl_final_hisab');
		$this->db->where('ledger_id', $user_id);

		if (!empty($start_datetime) && !empty($end_datetime)) {
			$start_date_only = date('Y-m-d', strtotime($start_datetime));
			$end_date_only   = date('Y-m-d', strtotime($end_datetime));

			$this->db->where("STR_TO_DATE(date, '%d-%m-%Y') >=", $start_date_only);
			$this->db->where("STR_TO_DATE(date, '%d-%m-%Y') <",  $end_date_only);
		}

		$pl_data = $this->db->get()->result();

		$pl_by_date = [];
		foreach ($pl_data as $pl) {
			$ymd = date('Y-m-d', strtotime(str_replace('/', '-', $pl->date)));
			$pl_by_date[$ymd] = (float) $pl->final_hisab;
		}

		// 5. Build final statement
		$statement = [];
		$balance = 0;

		$all_dates = array_unique(array_merge(array_keys($tx_by_date), array_keys($pl_by_date)));
		sort($all_dates);

		foreach ($all_dates as $date) {
			// Transactions
			if (isset($tx_by_date[$date])) {
				foreach ($tx_by_date[$date] as $row) {
					$deposit = '-';
					$withdraw = '-';

					if ($row->receiver_id == $user_id) {
						$balance += $row->amount;
						$deposit = number_format($row->amount, 2);
					} elseif ($row->sender_id == $user_id && $row->status == 1) {
						$balance -= $row->amount;
						$withdraw = number_format($row->amount, 2);
					} else {
						continue;
					}

					$statement[] = [
						'datetime' => $row->created_at,
						'deposit'  => $deposit,
						'withdraw' => $withdraw,
						'pl'       => '',
						'balance'  => number_format($balance, 2),
						'from_to'  => "{$row->sender_name} ➜ {$row->receiver_name}"
					];
				}
			}

			// P/L Adjustment
			if (isset($pl_by_date[$date])) {
				$pl_value = $pl_by_date[$date];

				if ($pl_value < 0) {
					$balance += abs($pl_value); // loss
				} else {
					$balance -= $pl_value; // profit
				}

				$statement[] = [
					'datetime' => $date . ' 23:59:59',
					'deposit'  => '',
					'withdraw' => '',
					'pl'       => number_format($pl_value, 2),
					'balance'  => number_format($balance, 2),
					'from_to'  => 'P/L Adjustment'
				];
			}
		}

		return $statement;
	}
