	/*
	 * Get all tbl_get_tbl_member_result
	 */
	function get_tbl_member_result($params)
	{
		// $this->db->from('Tb_Date_shift_party_entry');
		// return $this->db->get()->result_array();
		$this->db->select('tbl_shift.shift_name,tbl_ledger.ledger_name,Tb_Date_shift_party_entry.*,TP_person.ledger_name as thirdperson_name');
		$this->db->from('Tb_Date_shift_party_entry');
		$this->db->join('tbl_shift', 'Tb_Date_shift_party_entry.ShiftId = tbl_shift.id', 'left');
		$this->db->join('tbl_ledger', 'Tb_Date_shift_party_entry.PartyId = tbl_ledger.id', 'left');
		$this->db->join('`tbl_ledger` `TP_person`', 'Tb_Date_shift_party_entry.TP_person = TP_person.id', 'left');
		//$this->db->order_by('id', 'desc');
		if (isset($params['fromdate']) && !empty($params['fromdate'])) {
			$this->db->where('Tb_Date_shift_party_entry.Date>', date('d-m-Y', strtotime($params['fromdate'])));
		}
		if (isset($params['todate']) && !empty($params['todate'])) {
			$this->db->where('Tb_Date_shift_party_entry.Date<=', date('d-m-Y', strtotime($params['todate'])));
		}
		if (isset($params['search_party']) && !empty($params['search_party'])) {
			$this->db->where('Tb_Date_shift_party_entry.PartyId', $params['search_party']);
		}
		if (isset($params['shift_name']) && !empty($params['shift_name'])) {
			$this->db->where('Tb_Date_shift_party_entry.ShiftId', $params['shift_name']);
		}
		$this->db->order_by('id', 'desc');
		$query = $this->db->get();
		//echo $this->db->last_query(); die;
		return $query->result_array();
	}

