tl.`akhar_commission` as ledgerakhar_commission, 
	(select topen.number from tbl_openno as topen where topen.shift_id = tdsp.ShiftId 
	AND topen.Date='" . date('d-m-Y', strtotime($params['date'])) . "' 
	AND tdsp.id= tdsp.id)  as number,

topen.date as opendate, 
ts.shift_name, 
tdsp.*, 
(tdsp.`Open_Number_amount`) as oamnt, 
(tdsp.`Akhar_Number_amount`) as akmnt, 
(tdsp.`Total_Number_amount`) as tamnt 
from 
`Tb_Date_shift_party_entry` as tdsp 
join tbl_shift as ts on ts.id = tdsp.ShiftId 
Left join tbl_openno as topen on topen.date = tdsp.Date 
join tbl_ledger as tl on tl.id = tdsp.PartyId 
where 
 tdsp.Date = '" . date('d-m-Y', strtotime($params['date'])) . "'group by tl.id";

		$query = $this->db->query($sql);
		//echo $this->db->last_query(); die; 
