	function ledger_till_date_result_today_admin($params)
	{

		$sql = "SELECT 
        tl.ledger_name, 
        tl.hissa AS pattiperc, 
        tl.openingbalance AS openingbalance, 
        tl.hissa_select AS hissa_select, 
        tl.dara_rate AS ledgerdara_rate, 
        tl.dara_commision AS ledgerdara_commision, 
        tl.akhar_rate AS ledgerakhar_rate, 
        tl.akhar_commission AS ledgerakhar_commission, 
        topen.number AS number,
        topen.date AS opendate, 
        ts.shift_name, 
        ust.shift_id,
        tdsp.*, 
        tdsp.Open_Number_amount AS oamnt, 
        tdsp.Akhar_Number_amount AS akmnt, 
        tdsp.Total_Number_amount AS tamnt 
    FROM 
        Tb_Date_shift_party_entry AS tdsp
    JOIN  
        user_shift_timings AS ust ON ust.id = tdsp.shiftid 
    JOIN 
        tbl_shift AS ts ON ts.id = ust.shift_id
    LEFT JOIN 
        tbl_openno AS topen 
            ON topen.shift_id = ts.id
           AND topen.date_parsed = tdsp.ndate
    JOIN 
        tbl_ledger AS tl ON tl.id = tdsp.PartyId 
    WHERE 
        tdsp.PartyId = '" . $params['ledger_id'] . "' 
        AND tdsp.ndate = '" . date('Y-m-d', strtotime($params['date'])) . "'
        AND tl.updated_by = " . $this->session->userdata['id'] . " 
    GROUP BY 
        tdsp.id, tl.id, tdsp.ndate;";

		$query = $this->db->query($sql);
		$data['today'] = $query->result_array();

		$first_day_this_month = date('Y-m-01');

		$sqlold = "SELECT 
        tl.ledger_name,
        tl.hissa as pattiperc,
        tl.openingbalance as openingbalance,
        tl.hissa_select as hissa_select,
        tl.dara_rate as ledgerdara_rate,
        tl.dara_commision as ledgerdara_commision,
        tl.akhar_rate as ledgerakhar_rate,
        tl.akhar_commission as ledgerakhar_commission,
        topen.number,
        topen.date as opendate,
        ts.shift_name, 
        tdsp.*,
        tdsp.Open_Number_amount as oamnt, 
        tdsp.Akhar_Number_amount as akmnt,
        tdsp.Total_Number_amount as tamnt 
    FROM 
        Tb_Date_shift_party_entry AS tdsp 
    JOIN user_shift_timings AS ust ON ust.id = tdsp.shiftid
    JOIN tbl_shift AS ts ON ts.id = ust.shift_id
    JOIN tbl_openno AS topen ON topen.date_parsed = tdsp.ndate
    JOIN tbl_ledger AS tl ON tl.id = tdsp.PartyId
    WHERE 
        tdsp.PartyId = '" . $params['ledger_id'] . "' 
        AND tl.updated_by = " . $this->session->userdata['id'] . " ";

		if (strtotime($first_day_this_month) == strtotime(date('Y-m-d', strtotime($params['date'])))) {
			$sqlold .= "AND tdsp.ndate = '" . date('Y-m-d', strtotime($params['date'])) . "'
        GROUP BY tdsp.id";
		} else {
			$sqlold .= "AND tdsp.ndate < '" . date('Y-m-d', strtotime($params['date'])) . "'
        AND tdsp.ndate >= '" . date('Y-m-d', strtotime($first_day_this_month)) . "'
        GROUP BY tdsp.id";
		}

		if (strtotime($first_day_this_month) == strtotime(date('Y-m-d', strtotime($params['date'])))) {
			$data['before'] = array();
		} else {
			$query = $this->db->query($sqlold);
			$data['before'] = $query->result_array();
		}

		return $data;
	}


	function ledger_till_date_result_today($params)
{
    // Convert the input date to Y-m-d format (if it's not already)
    $formatted_date = date('Y-m-d', strtotime($params['date']));

    // --------------------
    // Query for today's result
    // --------------------
    $sql = "SELECT 
                tl.ledger_name, 
                tl.hissa AS pattiperc, 
                tl.openingbalance AS openingbalance, 
                tl.hissa_select AS hissa_select, 
                tl.dara_rate AS ledgerdara_rate, 
                tl.dara_commision AS ledgerdara_commision, 
                tl.akhar_rate AS ledgerakhar_rate, 
                tl.akhar_commission AS ledgerakhar_commission, 
                topen.number AS number,
                topen.date AS opendate, 
                ts.shift_name, 
                ust.shift_id,
                tdsp.*, 
                tdsp.Open_Number_amount AS oamnt, 
                tdsp.Akhar_Number_amount AS akmnt, 
                tdsp.Total_Number_amount AS tamnt 
            FROM Tb_Date_shift_party_entry AS tdsp
            JOIN user_shift_timings AS ust 
                ON ust.id = tdsp.shiftid 
            JOIN tbl_shift AS ts 
                ON ts.id = ust.shift_id
            LEFT JOIN tbl_openno AS topen 
                ON topen.shift_id = ust.id 
               AND topen.date_parsed = tdsp.ndate
               AND topen.updated_by != 1
            JOIN tbl_ledger AS tl 
                ON tl.id = tdsp.PartyId 
            WHERE tdsp.PartyId = " . $this->db->escape($params['ledger_id']) . "
              AND tdsp.ndate = " . $this->db->escape($formatted_date) . "
              AND tdsp.status = 1
            GROUP BY ts.id, tl.id, ust.shift_id, topen.number, tdsp.ndate";

    // Debug
    // echo "Today's SQL Query: <br>" . $sql . "<br><br>"; die;

    $query = $this->db->query($sql);
    $data['today'] = $query->result_array();

    // --------------------
    // Query for previous data (before today, within this month)
    // --------------------
    $first_day_this_month = date('Y-m-01', strtotime($formatted_date));

    $sqlold = "SELECT 
                    tl.ledger_name,
                    tl.hissa AS pattiperc,
                    tl.openingbalance AS openingbalance,
                    tl.hissa_select AS hissa_select,
                    tl.dara_rate AS ledgerdara_rate,
                    tl.dara_commision AS ledgerdara_commision,
                    tl.akhar_rate AS ledgerakhar_rate,
                    tl.akhar_commission AS ledgerakhar_commission,
                    topen.number,
                    topen.date AS opendate,
                    ts.shift_name, 
                    tdsp.*, 
                    tdsp.Open_Number_amount AS oamnt, 
                    tdsp.Akhar_Number_amount AS akmnt,
                    tdsp.Total_Number_amount AS tamnt
                FROM Tb_Date_shift_party_entry AS tdsp
                JOIN user_shift_timings AS ust 
                    ON ust.id = tdsp.shiftid
                JOIN tbl_shift AS ts 
                    ON ts.id = ust.shift_id
                LEFT JOIN tbl_openno AS topen 
                    ON topen.date_parsed = tdsp.ndate
                   AND topen.shift_id = ust.id
                   AND topen.updated_by != 1
                JOIN tbl_ledger AS tl 
                    ON tl.id = tdsp.PartyId
                WHERE tdsp.status = 1
                  AND tdsp.PartyId = " . $this->db->escape($params['ledger_id']);

    if ($first_day_this_month == $formatted_date) {
        // If first day of month → only today’s data, no previous
        $sqlold .= " AND tdsp.ndate = " . $this->db->escape($formatted_date) . "
                     GROUP BY tdsp.id";
        $data['before'] = [];
    } else {
        $sqlold .= " AND tdsp.ndate < " . $this->db->escape($formatted_date) . "
                     AND tdsp.ndate >= " . $this->db->escape($first_day_this_month) . "
                     GROUP BY tdsp.id";

        // Debug
        // echo "Previous Data SQL Query: <br>" . $sqlold . "<br><br>";

        $query = $this->db->query($sqlold);
        $data['before'] = $query->result_array();
    }

    return $data;
}
